CREATE OR REPLACE FUNCTION enforce_closed_correction_status_only() RETURNS trigger AS $$
BEGIN
  IF current_setting('passionedu.allow_history_cleanup', true) = 'on' THEN RETURN NEW; END IF;
  IF OLD."status" = 'CLOSED' AND NEW."status" = 'CANCELLED' AND ROW(OLD."schoolId", OLD."studentId", OLD."collectionRunId", OLD."schoolYearId", OLD."billingMonth", OLD."rosterAsOf", OLD."studentCodeSnapshot", OLD."studentNameSnapshot", OLD."enrollmentIdSnapshot", OLD."enrollmentLifecycleSnapshot", OLD."enrollmentEffectiveFromSnapshot", OLD."enrollmentEndedOnSnapshot", OLD."classAssignmentIdSnapshot", OLD."classAssignmentEffectiveFromSnapshot", OLD."classAssignmentEffectiveToSnapshot", OLD."classIdSnapshot", OLD."classNameSnapshot", OLD."selectionProvenance", OLD."total", OLD."issuedAt", OLD."bankAccountIdSnapshot", OLD."receivingBankSnapshot", OLD."accountNumberSnapshot", OLD."accountHolderNameSnapshot", OLD."transferContentSnapshot", OLD."obligationLinesSnapshot", OLD."obligationTotalSnapshot", OLD."financePolicyEffectiveFrom", OLD."dueDaysAfterIssueSnapshot", OLD."taxTreatmentSnapshot", OLD."debtScopeSnapshot", OLD."reversalModeSnapshot", OLD."dueOn", OLD."revisesInvoiceId", OLD."revisionReason", OLD."createdAt") IS DISTINCT FROM ROW(NEW."schoolId", NEW."studentId", NEW."collectionRunId", NEW."schoolYearId", NEW."billingMonth", NEW."rosterAsOf", NEW."studentCodeSnapshot", NEW."studentNameSnapshot", NEW."enrollmentIdSnapshot", NEW."enrollmentLifecycleSnapshot", NEW."enrollmentEffectiveFromSnapshot", NEW."enrollmentEndedOnSnapshot", NEW."classAssignmentIdSnapshot", NEW."classAssignmentEffectiveFromSnapshot", NEW."classAssignmentEffectiveToSnapshot", NEW."classIdSnapshot", NEW."classNameSnapshot", NEW."selectionProvenance", NEW."total", NEW."issuedAt", NEW."bankAccountIdSnapshot", NEW."receivingBankSnapshot", NEW."accountNumberSnapshot", NEW."accountHolderNameSnapshot", NEW."transferContentSnapshot", NEW."obligationLinesSnapshot", NEW."obligationTotalSnapshot", NEW."financePolicyEffectiveFrom", NEW."dueDaysAfterIssueSnapshot", NEW."taxTreatmentSnapshot", NEW."debtScopeSnapshot", NEW."reversalModeSnapshot", NEW."dueOn", NEW."revisesInvoiceId", NEW."revisionReason", NEW."createdAt") THEN RAISE EXCEPTION 'Closed correction cancellation can only change status'; END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER closed_correction_status_only_guard BEFORE UPDATE ON "Invoice" FOR EACH ROW EXECUTE FUNCTION enforce_closed_correction_status_only();
